            parts = []
            i = 0
            m = len(cur)
            while i < m:
                j = i + 1
                while j < m and cur[j] == cur[i]:
                    j += 1
                parts.append(str(j - i))
                parts.append(cur[i])
                i = j
            cur = "".join(parts)
        return cur

