        out = []
        while i >= 0 or j >= 0 or carry:
            s = carry
            if i >= 0:
                s += ord(a[i]) - 48
                i -= 1
            if j >= 0:
                s += ord(b[j]) - 48
                j -= 1
            out.append(str(s & 1))
            carry = s >> 1
        return "".join(reversed(out))

